    /**
     * Method to retrieve the Operator via OperatorFetchOneSummary
     * @param 	summary OperatorFetchOneSummary 
     * @return 	OperatorFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Operator getOperator( OperatorFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OperatorFetchOneSummary arg cannot be null" );
    	
    	Operator entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Operator
        	// --------------------------------------
        	CompletableFuture<Operator> futureEntity = queryGateway.query(new FindOperatorQuery( new LoadOperatorFilter( summary.getOperatorId() ) ), ResponseTypes.instanceOf(Operator.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Operator with id " + summary.getOperatorId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


